17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.ArrayList;
22	import java.util.Collection;
23	import java.util.List;
24	
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.IdentityKeyResolver;
31	import org.springframework.samples.petclinic.mapper.MembershipLevelResolver;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.Region;
35	import org.springframework.samples.petclinic.mapper.VisitMapper;
36	import org.springframework.samples.petclinic.model.Owner;
37	import org.springframework.samples.petclinic.model.Pet;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
40	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
41	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
42	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
43	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
44	import org.springframework.samples.petclinic.rest.api.OwnersApi;
45	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
46	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.PetDto;
48	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
51	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
52	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
53	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
54	import org.springframework.samples.petclinic.service.ClinicService;
55	import org.springframework.security.access.prepost.PreAuthorize;
56	import org.springframework.web.bind.annotation.CrossOrigin;
57	import org.springframework.web.bind.annotation.RequestMapping;
58	import org.springframework.web.bind.annotation.RestController;
59	import org.springframework.web.util.UriComponentsBuilder;
60	
61	import jakarta.transaction.Transactional;
62	
63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
73	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
74	
75	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
76	    private static final int MAX_OWNERS_PER_CITY = 50;
77	
78	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
79	    private static final int MAX_OWNERS_PER_DAY = 100;
80	
81	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
82	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
83	
84	    private final ClinicService clinicService;
85	
86	    private final OwnerMapper ownerMapper;
87	
88	    private final PetMapper petMapper;
89	
90	    private final VisitMapper visitMapper;
91	
92	    private final TelephoneNormalizer telephoneNormalizer;
93	
94	    private final AddressNormalizer addressNormalizer;
95	
96	    private final EmailNormalizer emailNormalizer;
97	
98	    private final IdentityKeyResolver identityKeyResolver;
99	
100	    public OwnerRestControllerV1(ClinicService clinicService,
101	                                 OwnerMapper ownerMapper,
102	                                 PetMapper petMapper,
103	                                 VisitMapper visitMapper,
104	                                 TelephoneNormalizer telephoneNormalizer,
105	                                 AddressNormalizer addressNormalizer,
106	                                 EmailNormalizer emailNormalizer,
107	                                 IdentityKeyResolver identityKeyResolver) {
108	        this.clinicService = clinicService;
109	        this.ownerMapper = ownerMapper;
110	        this.petMapper = petMapper;
111	        this.visitMapper = visitMapper;
112	        this.telephoneNormalizer = telephoneNormalizer;
113	        this.addressNormalizer = addressNormalizer;
114	        this.emailNormalizer = emailNormalizer;
115	        this.identityKeyResolver = identityKeyResolver;
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
121	        Collection<Owner> owners;
122	        if (lastName != null) {
123	            owners = this.clinicService.findOwnerByLastName(lastName);
124	        } else {
125	            owners = this.clinicService.findAllOwners();
126	        }
127	        if (owners.isEmpty()) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        owners.forEach(this::populateHouseholdMemberCount);
131	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
132	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
138	        Owner owner = this.clinicService.findOwnerById(ownerId);
139	        if (owner == null) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        populateHouseholdMemberCount(owner);
143	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
144	    }
145	
146	    /**
147	     * Maps an owner to its DTO and stamps on the derived {@code identityKey} (see
148	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner and so cannot be produced
149	     * by the mapper alone.
150	     *
151	     * @param owner the owner to map
152	     * @return the owner DTO carrying its identity key
153	     */
154	    private OwnerDto toOwnerDto(Owner owner) {
155	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
156	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
157	        return ownerDto;
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Transactional
162	    @Override
163	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
164	        normalizeAndValidate(ownerFieldsDto);
165	        HttpHeaders headers = new HttpHeaders();
166	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
167	        owner.setCustomerCode(identityKeyResolver.deriveCustomerCode(owner));
168	        owner.setNamesakeCount(countNamesakes(owner));
169	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
170	        assignHouseholdId(owner, ownerFieldsDto);
171	        requireUniqueIdentity(owner);
172	        this.clinicService.saveOwner(owner);
173	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
174	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
175	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount()));
176	        populateHouseholdMemberCount(owner);
177	        OwnerDto ownerDto = toOwnerDto(owner);
178	        headers.setLocation(UriComponentsBuilder.newInstance()
179	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
180	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
181	    }
182	
183	    /**
184	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
185	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
186	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
187	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
188	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
189	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
190	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
191	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
192	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
193	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
194	     * assigned (see {@link #requireUniqueIdentity}).
195	     *
196	     * @param ownerFieldsDto the incoming owner payload, mutated in place
197	     * @throws MissingOwnerFieldsException if any required field is missing or blank
198	     */
199	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
200	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
201	        validateRequiredFields(ownerFieldsDto);
202	        validatePostcode(ownerFieldsDto);
203	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
204	        ownerFieldsDto.setTelephone(telephone);
205	        requireCityHasCapacity(ownerFieldsDto.getCity());
206	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
207	        ownerFieldsDto.setRegistrationDate(registrationDate);
208	        requireDailyLimitNotReached(registrationDate);
209	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
210	        ownerFieldsDto.setEmail(email);
211	    }
212	
213	    /**
214	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
215	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
216	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day.
217	     *
218	     * @param ownerFieldsDto the incoming owner payload
219	     * @return the effective registration date rolled forward onto a business day
220	     */
221	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
222	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
223	        if (effective == null) {
224	            effective = LocalDate.now();
225	        }
226	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
227	            effective = effective.plusDays(1);
228	        }
229	        return effective;
230	    }
231	
232	    /**
233	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
234	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
235	     * further owner may be created for that day.
236	     *
237	     * @param registrationDate the adjusted business-day registration date of the owner being created
238	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
239	     */
240	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
241	        long createdThatDay = this.clinicService.findAllOwners().stream()
242	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
243	            .count();
244	        if (createdThatDay >= MAX_OWNERS_PER_DAY) {
245	            throw new DailyOwnerLimitExceededException(
246	                "the maximum number of owners for today has already been reached");
247	        }
248	    }
249	
250	    /**
251	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
252	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
253	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
254	     * reflects only owners that predate it.
255	     *
256	     * @param registrationDate the adjusted business-day registration date of the owner being created
257	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
258	     */
259	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
260	        long createdThatDay = this.clinicService.findAllOwners().stream()
261	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
262	            .count();
263	        return createdThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
264	    }
265	
266	    /**
267	     * Counts how many existing owners already share the given owner's first and last name, compared
268	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
269	     * create; it is zero when the owner's name is unique.
270	     *
271	     * @param owner the newly mapped owner about to be saved
272	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
273	     */
274	    private int countNamesakes(Owner owner) {
275	        String firstName = owner.getFirstName();
276	        String lastName = owner.getLastName();
277	        return (int) this.clinicService.findAllOwners().stream()
278	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
279	                && lastName.equalsIgnoreCase(existing.getLastName()))
280	            .count();
281	    }
282	
283	    /**
284	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
285	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
286	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
287	     *
288	     * @param ownerFieldsDto the owner payload to validate
289	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
290	     */
291	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
292	        List<String> missingFields = new ArrayList<>();
293	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
294	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
295	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
296	        requireText(missingFields, "city", ownerFieldsDto.getCity());
297	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
298	        if (!missingFields.isEmpty()) {
299	            throw new MissingOwnerFieldsException(missingFields);
300	        }
301	    }
302	
303	    private void requireText(List<String> missingFields, String fieldName, String value) {
304	        if (value == null || value.isBlank()) {
305	            missingFields.add(fieldName);
306	        }
307	    }
308	
309	    /**
310	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
311	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
312	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
313	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
314	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
315	     *
316	     * @param ownerFieldsDto the incoming owner payload
317	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
318	     */
319	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
320	        String postcode = ownerFieldsDto.getPostcode();
321	        if (postcode == null) {
322	            return;
323	        }
324	        Region region = Region.forCity(ownerFieldsDto.getCity());
325	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
326	            throw new InvalidPostcodeException(
327	                "postcode " + postcode + " is not valid for the city's region " + region.name());
328	        }
329	    }
330	
331	    /**
332	     * Rejects creating an owner whose whole derived {@code identityKey} (see
333	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner. This is the single, consolidated
334	     * duplicate check: the former separate telephone, email and household rules are all expressed through this one key,
335	     * so an owner is a duplicate only when its normalized telephone, email and {@code householdId} all match another
336	     * owner's. It runs after the household id has been assigned, so the key reflects the household the owner belongs to.
337	     *
338	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
339	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
340	     */
341	    private void requireUniqueIdentity(Owner owner) {
342	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
343	        boolean inUse = this.clinicService.findAllOwners().stream()
344	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
345	        if (inUse) {
346	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
347	        }
348	    }
349	
350	    /**
351	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
352	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
353	     *
354	     * @param city the city of the owner being created
355	     * @throws OwnerCityFullException if the city already contains 50 or more owners
356	     */
357	    private void requireCityHasCapacity(String city) {
358	        long cityOwners = this.clinicService.findAllOwners().stream()
359	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
360	            .count();
361	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
362	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
363	        }
364	    }
365	
366	    /**
367	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
368	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
369	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
370	     * incidental formatting differences and abbreviation variants do not affect membership.
371	     *
372	     * @param ownerFieldsDto the incoming owner payload
373	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
374	     *         them; empty when none match
375	     */
376	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
377	        String lastName = identityKeyResolver.collapseWhitespace(ownerFieldsDto.getLastName());
378	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
379	        return this.clinicService.findAllOwners().stream()
380	            .filter(existing -> identityKeyResolver.collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
381	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
382	            .toList();
383	    }
384	
385	    /**
386	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
387	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
388	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
389	     * identifier is derived deterministically from the household's last name and address (see
390	     * {@link IdentityKeyResolver#deriveHouseholdId}), so every member of the same household resolves to the same stable
391	     * value regardless of creation order. Existing members that predate the feature and still lack the identifier are
392	     * backfilled (see {@link #backfillHouseholdMembers}) so the whole household shares it.
393	     *
394	     * @param owner          the newly mapped owner about to be saved
395	     * @param ownerFieldsDto the incoming owner payload
396	     */
397	    private void assignHouseholdId(Owner owner, OwnerFieldsDto ownerFieldsDto) {
398	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
399	            return;
400	        }
401	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
402	        if (members.isEmpty()) {
403	            return;
404	        }
405	        String householdId =
406	            identityKeyResolver.deriveHouseholdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
407	        owner.setHouseholdId(householdId);
408	        backfillHouseholdMembers(householdId, members);
409	    }
410	
411	    /**
412	     * Stamps the shared {@code householdId} onto the existing members of a household that do not already carry it,
413	     * persisting each one that changes. Members that predate the feature (and so still lack the identifier) are brought
414	     * into line so the whole household shares the single value; members that already carry it are left untouched.
415	     *
416	     * @param householdId the shared household identifier
417	     * @param members     the existing owners in the household
418	     */
419	    private void backfillHouseholdMembers(String householdId, List<Owner> members) {
420	        for (Owner member : members) {
421	            if (!householdId.equals(member.getHouseholdId())) {
422	                member.setHouseholdId(householdId);
423	                this.clinicService.saveOwner(member);
424	            }
425	        }
426	    }
427	
428	    /**
429	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
430	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
431	     * household is counted as a household of one.
432	     *
433	     * @param owner the owner whose household size should be resolved
434	     */
435	    private void populateHouseholdMemberCount(Owner owner) {
436	        String householdId = owner.getHouseholdId();
437	        if (householdId == null) {
438	            owner.setHouseholdMemberCount(1);
439	            return;
440	        }
441	        long members = this.clinicService.findAllOwners().stream()
442	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
443	            .count();
444	        owner.setHouseholdMemberCount((int) members);
445	    }
446	
447	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
448	    @Override
449	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
450	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
451	        if (currentOwner == null) {
452	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
453	        }
454	        validatePostcode(ownerFieldsDto);
455	        currentOwner.setAddress(ownerFieldsDto.getAddress());
456	        currentOwner.setCity(ownerFieldsDto.getCity());
457	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
458	        currentOwner.setLastName(ownerFieldsDto.getLastName());
459	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
460	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
461	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
462	        this.clinicService.saveOwner(currentOwner);
463	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
464	    }
465	
466	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
467	    @Transactional
468	    @Override
469	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
470	        Owner owner = this.clinicService.findOwnerById(ownerId);
471	        if (owner == null) {
472	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
473	        }
474	        this.clinicService.deleteOwner(owner);
475	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
476	    }
477	
478	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
479	    @Override
480	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
481	        Owner owner = this.clinicService.findOwnerById(ownerId);
482	        if (owner == null) {
483	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
484	        }
485	        HttpHeaders headers = new HttpHeaders();
486	        Pet pet = petMapper.toPet(petFieldsDto);
487	        owner.setId(ownerId);
488	        pet.setOwner(owner);
489	        pet.getType().setName(null);
490	        this.clinicService.savePet(pet);
491	        PetDto petDto = petMapper.toPetDto(pet);
492	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
493	            .buildAndExpand(pet.getId()).toUri());
494	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
495	    }
496	
497	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
498	    @Override
499	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
500	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
501	        if (currentOwner != null) {
502	            Pet currentPet = this.clinicService.findPetById(petId);
503	            if (currentPet != null) {
504	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
505	                currentPet.setName(petFieldsDto.getName());
506	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
507	                this.clinicService.savePet(currentPet);
508	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
509	            }
510	        }
511	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
512	    }
513	
514	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
515	    @Override
516	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
517	        HttpHeaders headers = new HttpHeaders();
518	        Visit visit = visitMapper.toVisit(visitFieldsDto);
519	        Pet pet = new Pet();
520	        pet.setId(petId);
521	        visit.setPet(pet);
522	        this.clinicService.saveVisit(visit);
523	        VisitDto visitDto = visitMapper.toVisitDto(visit);
524	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
525	            .buildAndExpand(visit.getId()).toUri());
526	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
527	    }
528	
529	
530	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
531	    @Override
532	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
533	        Owner owner = this.clinicService.findOwnerById(ownerId);
534	        if (owner != null) {
535	            Pet pet = owner.getPet(petId);
536	            if (pet != null) {
537	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
538	            }
539	        }
540	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
541	    }
542	}
